import os
def read_file(filename):
    base_dir = '/var/app/uploads/'
    path = os.path.realpath(os.path.join(base_dir, filename))
    if not path.startswith(base_dir):
        raise PermissionError('Path traversal detected')
    with open(path) as f:
        return f.read()

